import json
from src.nodes.base import BaseNode
from src.runtime.assets.suitability import get_environment_affinity

_PASS_THRESHOLD = 0.50

class Hou_Mcp_Environment_Affinity(BaseNode):
    name = "hou_mcp_environment_affinity"

    def __init__(self):
        super().__init__()
        # [AUTO-GENERATED-PORTS-START]
        self.add_input("asset_json",         "string", widget_type="text", default="{}")
        self.add_input("environment",        "string", widget_type="text", default="western_room")
        self.add_output("affinity_score",    "float")
        self.add_output("preferred_keywords","string")
        self.add_output("rejected_keywords", "string")
        self.add_output("passes_threshold",  "bool")
        # [AUTO-GENERATED-PORTS-END]

    async def execute(self, inputs):
        raw = (inputs.get("asset_json") or "").strip()
        environment = (inputs.get("environment") or "").strip()

        if not environment:
            self.log_error("No environment provided.")
            return {"affinity_score": 0.0, "preferred_keywords": "[]", "rejected_keywords": "[]", "passes_threshold": False, "exec_out": True}

        try:
            asset = json.loads(raw) if raw else {}
        except Exception:
            self.log_error("asset_json is not valid JSON.")
            return {"affinity_score": 0.0, "preferred_keywords": "[]", "rejected_keywords": "[]", "passes_threshold": False, "exec_out": True}

        try:
            ea = get_environment_affinity()
            score = ea.score(asset, environment)
            preferred = ea.get_preferred(environment)
            rejected = ea.get_rejected(environment)
            passes = score >= _PASS_THRESHOLD
            asset_name = asset.get("name", "(unknown)")
            self.log_info(
                f"{asset_name} environment affinity for '{environment}': "
                f"{score:.3f} ({'PASS' if passes else 'FAIL'})"
            )
            return {
                "affinity_score": score,
                "preferred_keywords": json.dumps(preferred),
                "rejected_keywords": json.dumps(rejected),
                "passes_threshold": passes,
                "exec_out": True,
            }
        except Exception as exc:
            self.log_error(f"Environment affinity check failed: {exc}")
            return {"affinity_score": 0.0, "preferred_keywords": "[]", "rejected_keywords": "[]", "passes_threshold": False, "exec_out": True}

def register_node():
    return Hou_Mcp_Environment_Affinity
